DELETE FROM requisito_proyecto
WHERE requisito_proyecto_requisito_id IN (
    SELECT id FROM requisito WHERE codigo = 'T-FORMATO-INSCRIPCION-TESIS'
);

DELETE FROM requisito_proyecto
WHERE requisito_proyecto_requisito_id IN (
    SELECT id FROM requisito WHERE codigo = 'REQ_PROPUESTA'
)
AND requisito_proyecto_proyecto_id IN (
    SELECT id FROM proyecto WHERE proyecto_modalidad_id = 9004
);
